test "$(git rev-parse FETCH_HEAD)" = "f376c4aa57d393e37626648fba3d0d4cf2f36edf"
python3 -B - <<'PY'
import json,subprocess,urllib.request
rid="run_mwymf5g4_c4b6e6cd24"
try:
 o=json.load(urllib.request.urlopen("http://127.0.0.1:8787/v1/status/"+rid,timeout=5));d=o.get("durable") or {}
 print("PREVIOUS_RUN "+json.dumps({"id":rid,"state":o.get("state"),"job_status":d.get("job_status"),"active":d.get("active_in_process"),"cursor":d.get("workflow_cursor"),"error":d.get("last_execution_error"),"last_failure":d.get("last_execution_failure")})[:6000],flush=True)
except Exception as e: print("PREVIOUS_RUN_LOOKUP="+type(e).__name__,flush=True)
p={f:subprocess.check_output(["git","show","f376c4aa57d393e37626648fba3d0d4cf2f36edf:"+f],text=True) for f in ["scripts/real-debug-corpus.json","scripts/real-debug-suite.cjs"]}
node=r'''
const fs=require("node:fs"),os=require("node:os"),path=require("node:path"),Module=require("node:module");
const source=JSON.parse(fs.readFileSync(0,"utf8")),m=new Module("/app/scripts/real-debug-suite.cjs",module);m.filename="/app/scripts/real-debug-suite.cjs";m.paths=Module._nodeModulePaths("/app/scripts");const orig=m.require.bind(m);m.require=n=>n==="./real-debug-corpus.json"?JSON.parse(source["scripts/real-debug-corpus.json"]):orig(n);m._compile(source["scripts/real-debug-suite.cjs"],m.filename);
