let results=[];for(const c of corpus.cases){const root=fs.mkdtempSync(path.join(os.tmpdir(),"debugai-oracle-fixture-"));try{const r=fixtureCheck(c,root);results.push({id:r.id,pass:r.pass,...(!r.pass?{runs:r.runs}:{})});}finally{fs.rmSync(root,{recursive:true,force:true});}}
console.log("FIXTURE_QUALIFICATION="+JSON.stringify({total:results.length,passed:results.filter(r=>r.pass).length,failed:results.filter(r=>!r.pass)}));if(results.some(r=>!r.pass))process.exitCode=4;
'''
subprocess.run(["docker","exec","-i","debug-ai-debug-ai-1","node","-e",node],input=json.dumps(p),text=True,check=True)
